import{_ as t,r as a,c as r,d as i,a as n,o}from"./app-DxeoH4H7.js";const p={},c=n('<p>PmHub 就是为大家找工作拿 offer 服务的，所以我们也花了很多心思为大家精心准备了简历模板。</p><p>并且我们也会不断向<a href="https://laigeoffer.cn/zsxq/" target="_blank" rel="noopener noreferrer">球友们</a>征集关于 PmHub 的真实面经，并在星球里及时更新，每隔一周，也会把真实面经同步到这个帖子中供大家参考。</p><p>下面是最近刚收集到的：</p><h3 id="q-项目负责什么-你做的这个模块做了什么" tabindex="-1"><a class="header-anchor" href="#q-项目负责什么-你做的这个模块做了什么"><span>Q：项目负责什么，你做的这个模块做了什么</span></a></h3><p>A1：我在项目中主要负责 project 模块的后端开发，该模块是 PmHub 的核心，可以自定义项目和任务，以及分配任务，还可以在任务中添加评论，任务完成后可以通过审批流进行任务流转，实现项目-任务之间的完美闭环。</p><figure><img src="https://cdn.tobebetterjavaer.com/stutymore/real-interview-20240809175114.png" alt="PmHub 项目管理页面" tabindex="0" loading="lazy"><figcaption>PmHub 项目管理页面</figcaption></figure><p>在任务审批设置时，为了保证审批状态一致性，我使用了基于 Redis 的分布式锁，通过自定义注解+ AOP 完成了加锁和解锁的控制。</p><p>在添加任务时，需要添加成员、更新审批设置、更新日志等一系列操作，我通过 Seata 添加分布式事务，通过 @GlobalTransactional 注解保证添加任务时的事务一致性。</p><p>在新建任务后，需要指派人员，并通知到对应的人员，我使用了 RocketMQ 来进行消息推送，实现了异步解耦的同时极大的提高了系统的稳定性。</p><p>A2：在 PmHub 项目中，我主要负责的是 pmhub-auth 认证中心模块。这个模块的核心职责是管理和验证用户身份，确保只有经过认证的用户才能访问系统的各种资源和功能。</p><figure><img src="https://cdn.tobebetterjavaer.com/stutymore/real-interview-20240809175052.png" alt="PmHub 权限管理" tabindex="0" loading="lazy"><figcaption>PmHub 权限管理</figcaption></figure><p>我使用了 Spring Security 和 JWT 来实现这些功能。具体实现上，我首先配置了 Spring Security，定义了各种认证和授权规则，包括为不同的 URL 路径设置不同的访问控制策略。</p><p>在身份验证过程中，我使用了 JSON Web Token (JWT) 来管理用户会话。每当用户成功登录时，系统会生成一个 JWT 令牌，并将其返回给客户端。这个令牌包含了用户的身份信息和权限信息，并经过签名以防止篡改。客户端在后续的请求中会携带这个令牌，服务器则通过验证令牌的签名来确认用户的身份和权限。</p><p>在权限管理方面，我采用了基于角色的访问控制（RBAC）模型。每个用户可以拥有一个或多个角色，每个角色定义了一组权限。通过这种方式，可以灵活地管理用户的访问权限。例如，管理员角色拥有对所有资源的访问权限，而普通用户角色仅能访问其个人数据和有限的功能模块。</p><hr><p>一起冲刺 offer 的路上，你并不孤单。</p><p>目前我们已经挖掘了 10 个亮点供大家把 PmHub 写到简历上，都是能让 HR/面试官眼前一亮的，有深度有吸引力，包括：</p><ul><li>Gateway 实现自定义网关统一鉴权统计接口调用时间</li><li>使用 Redis+Lua 基于令牌桶实现限流</li><li>使用 RocketMQ 实现审批消息异步解耦</li><li>集成 OpenFeign+Sentinel 实现服务降级和网关流量控制</li><li>集成 Redis 分布式锁保障流程状态更新</li><li>通过分布式事务 Seata 保证任务审批状态一致性</li><li>自定义注解+AOP 实现服务接口鉴权和内部认证</li><li>整合 TTL 缓存用户数据</li><li>如何用 Docker 容器化部署项目</li><li>使用 Skywalking 监控项目性能</li><li>采用 Cache Aside 模式保证缓存和数据库一致性</li></ul><figure><img src="https://cdn.tobebetterjavaer.com/stutymore/20240611155429.png" alt="如何把 PmHub 写进简历" tabindex="0" loading="lazy"><figcaption>如何把 PmHub 写进简历</figcaption></figure><p>并且还配套详细的教程供大家学习，让大家真正做到知其然知其所以然。</p><figure><img src="https://cdn.tobebetterjavaer.com/stutymore/03.如何学习PmHub-20240702145210.png" alt="Seata 分布式事务保证任务审批状态一致性" tabindex="0" loading="lazy"><figcaption>Seata 分布式事务保证任务审批状态一致性</figcaption></figure><p>后面还会继续追加，让大家不再为写简历发愁（愁到掉头发😄）。</p><div class="hint-container tip"><p class="hint-container-title">为什么做知识星球</p><p>PmHub 的项目源码在 GitHub 和码云上是完全开源的，但教程我们确实花费了太多时间和心血，希望真心喜欢这个项目的小伙伴，以及从 PmHub 项目中得到帮助和提升的小伙伴能给予我们一点点肯定和支持。</p><p>这不仅能激励我们持续创作，为大家提供更多优质的开源项目，同时也能刺激我们向大家提供更高质量更长久的服务。</p><p>欢迎能理解我们的小伙伴加入<a href="https://laigeoffer.cn/zsxq/" target="_blank" rel="noopener noreferrer">二哥的编程星球</a>。</p><figure><img src="https://cdn.tobebetterjavaer.com/stutymore/07.项目真实面经-20240711211137.png" alt="已经有很多球友加入我们" tabindex="0" loading="lazy"><figcaption>已经有很多球友加入我们</figcaption></figure></div>',23);function l(m,s){const e=a("ZsxqContentBanner");return o(),r("div",null,[c,i(e)])}const g=t(p,[["render",l],["__file","real-interview.html.vue"]]),b=JSON.parse('{"path":"/pmhub/real-interview.html","title":"PmHub有真实面经吗？","lang":"zh-CN","frontmatter":{"title":"PmHub有真实面经吗？","description":"PmHub 是二哥编程星球 25 届秋招刚推出的微服务实战项目，刚刚上线一个月，目前已经有球友把 PmHub 写到简历上了，相信接下来就会有真实的面经，到时候一定第一时间分享出来。","head":[["meta",{"name":"keywords","content":"PmHub,pmhub,二哥的pmhub,pmhub真实面经,项目面经"}],["meta",{"property":"og:url","content":"https://laigeoffer.cn/pmhub/real-interview.html"}],["meta",{"property":"og:site_name","content":"来个offer"}],["meta",{"property":"og:title","content":"PmHub有真实面经吗？"}],["meta",{"property":"og:description","content":"PmHub 是二哥编程星球 25 届秋招刚推出的微服务实战项目，刚刚上线一个月，目前已经有球友把 PmHub 写到简历上了，相信接下来就会有真实的面经，到时候一定第一时间分享出来。"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://cdn.tobebetterjavaer.com/stutymore/real-interview-20240809175114.png"}],["meta",{"property":"og:locale","content":"zh-CN"}],["meta",{"property":"og:updated_time","content":"2024-08-09T12:57:08.000Z"}],["meta",{"property":"article:author","content":"苍何&沉默王二"}],["meta",{"property":"article:published_time","content":"2024-06-11T15:42:08.000Z"}],["meta",{"property":"article:modified_time","content":"2024-08-09T12:57:08.000Z"}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"PmHub有真实面经吗？\\",\\"image\\":[\\"https://cdn.tobebetterjavaer.com/stutymore/real-interview-20240809175114.png\\",\\"https://cdn.tobebetterjavaer.com/stutymore/real-interview-20240809175052.png\\",\\"https://cdn.tobebetterjavaer.com/stutymore/20240611155429.png\\",\\"https://cdn.tobebetterjavaer.com/stutymore/03.如何学习PmHub-20240702145210.png\\",\\"https://cdn.tobebetterjavaer.com/stutymore/07.项目真实面经-20240711211137.png\\"],\\"datePublished\\":\\"2024-06-11T15:42:08.000Z\\",\\"dateModified\\":\\"2024-08-09T12:57:08.000Z\\",\\"author\\":[{\\"@type\\":\\"Person\\",\\"name\\":\\"苍何&沉默王二\\",\\"url\\":\\"https://github.com/laigeoffer\\"}]}"]],"date":"2024-06-11T15:42:08.000Z","categories":["PmHub","项目介绍"]},"headers":[{"level":3,"title":"Q：项目负责什么，你做的这个模块做了什么","slug":"q-项目负责什么-你做的这个模块做了什么","link":"#q-项目负责什么-你做的这个模块做了什么","children":[]}],"git":{"createdTime":1721893733000,"updatedTime":1723208228000,"contributors":[{"name":"沉默王二","email":"www.qing_gee@163.com","commits":2}]},"readingTime":{"minutes":4.5,"words":1350},"filePathRelative":"pmhub/real-interview.md","localizedDate":"2024年6月11日"}');export{g as comp,b as data};
